import '@testing-library/jest-dom/vitest'

import { AxiosError, AxiosHeaders } from 'axios'
import { render, screen } from '@testing-library/react'
import { MemoryRouter } from 'react-router-dom'
import { beforeEach, describe, expect, it, vi } from 'vitest'

const mocks = vi.hoisted(() => ({ get: vi.fn() }))
vi.mock('../../services/apiClient', () => ({ apiClient: mocks }))

import { FamilyRiskPage } from './FamilyRiskPage'

const me = { id: 'm-1', familyId: 'f', displayName: 'Synthetic Member', dateOfBirth: '1990-01-01', role: 'Head' }

describe('FamilyRiskPage', () => {
  beforeEach(() => { mocks.get.mockReset() })

  it('shows an empty state when no approved indication exists', async () => {
    const notFound = new AxiosError('nf', '404', undefined, undefined, { status: 404, statusText: 'Not Found', data: {}, headers: {}, config: { headers: new AxiosHeaders() } })
    mocks.get.mockImplementation((url: string) => url === '/families/me' ? Promise.resolve({ data: { id: 'f', name: 'S', members: [me] } })
      : url === '/members/me' ? Promise.resolve({ data: me }) : Promise.reject(notFound))
    render(<MemoryRouter><FamilyRiskPage /></MemoryRouter>)
    expect(await screen.findByText('No approved screening indication')).toBeInTheDocument()
  })

  it('shows the doctor-approved screening indication', async () => {
    mocks.get.mockImplementation((url: string) => url === '/families/me' ? Promise.resolve({ data: { id: 'f', name: 'S', members: [me] } })
      : url === '/members/me' ? Promise.resolve({ data: me })
      : Promise.resolve({ data: { caseId: 'c', screeningGuidance: 'Please discuss appropriate screening with a licensed clinician.', approvedAt: '2026-09-02T00:00:00Z', disclaimer: 'Not a diagnosis.' } }))
    render(<MemoryRouter><FamilyRiskPage /></MemoryRouter>)
    expect(await screen.findByText('Please discuss appropriate screening with a licensed clinician.')).toBeInTheDocument()
  })
})
